import{identity,multiply,ortho,lookAt,sub,cross,normalize}from'./room-math.js';
const rgb=hex=>hex.slice(1).match(/../g).map(v=>parseInt(v,16)/255);
function material(m){const n=m.name.toLowerCase();if(n.includes('screen')||n.includes('diffuser'))return[6,.45,1];if(n.includes('floorboard'))return[10,.6,0];if(/wood|walnut|tabletop|cabinet|bed frame|bed end|bedpost|turned/.test(n))return[2,.48,0];if(/curtain|fabric|duvet|pillow|mattress|cushion|chair mesh|soft toy/.test(n))return[3,.95,0];if(/aluminium|sash|chassis|metal|gas lift|trackpad|phone/.test(n))return[4,.3,0];if(/window dark|wired glass/.test(n))return[5,.16,0];if(/wall|pelmet|ceiling|skirting/.test(n))return[1,.95,0];if(/paper|book|notebook|tissue/.test(n))return[8,.85,0];if(/lamp|cap|key|mouse/.test(n))return[9,.45,0];if(m.kind==='skin')return[7,.8,0];return[0,.8,0];}
function pack(parts){const out=[];for(const m of parts){const p=m.positions,col=rgb(m.color),mat=material(m),smooth=new Map();if(m.smooth)for(let i=0;i<p.length;i+=9){const a=p.slice(i,i+3),b=p.slice(i+3,i+6),c=p.slice(i+6,i+9),n=cross(sub(b,a),sub(c,a));for(let k=0;k<9;k+=3){const key=p.slice(i+k,i+k+3).map(v=>v.toFixed(5)).join(',');const old=smooth.get(key)||[0,0,0];smooth.set(key,old.map((v,j)=>v+n[j]));}}for(let i=0;i<p.length;i+=9){const n=normalize(cross(sub(p.slice(i+3,i+6),p.slice(i,i+3)),sub(p.slice(i+6,i+9),p.slice(i,i+3))));for(let k=0;k<9;k+=3){const point=p.slice(i+k,i+k+3),no=m.smooth?normalize(smooth.get(point.map(v=>v.toFixed(5)).join(','))):n;out.push(...point,...no,...col,...mat);}}}return new Float32Array(out);}
const vertex=`attribute vec3 position;attribute vec3 normal;attribute vec3 color;attribute vec3 material;uniform mat4 vp;uniform mat4 model;uniform mat4 lightVP;varying vec3 P;varying vec3 N;varying vec3 C;varying vec3 M;varying vec4 shadowCoord;void main(){vec4 world=model*vec4(position,1.);P=world.xyz;N=mat3(model)*normal;C=color;M=material;shadowCoord=lightVP*world;gl_Position=vp*world;}`;
const fragment=`precision highp float;
varying vec3 P;varying vec3 N;varying vec3 C;varying vec3 M;varying vec4 shadowCoord;
uniform vec3 eye;uniform float evening;uniform sampler2D shadowMap;uniform float hasShadow;
float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float noise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(hash(i),hash(i+vec2(1.,0.)),f.x),mix(hash(i+vec2(0.,1.)),hash(i+vec2(1.,1.)),f.x),f.y);}
float depthAt(vec2 uv){return dot(texture2D(shadowMap,uv),vec4(1./16777216.,1./65536.,1./256.,1.));}
float shadow(vec3 n,vec3 l){if(hasShadow<.5)return 1.;vec3 q=shadowCoord.xyz/shadowCoord.w*.5+.5;if(q.x<0.||q.x>1.||q.y<0.||q.y>1.||q.z>1.)return 1.;float bias=max(.0006,.002*(1.-dot(n,l))),s=0.;for(int x=-1;x<=1;x++)for(int y=-1;y<=1;y++){s+=q.z-bias<depthAt(q.xy+vec2(float(x),float(y))/1024.)?1.:.2;}return s/9.;}
vec3 film(vec3 c){return clamp((c*(2.51*c+.03))/(c*(2.43*c+.59)+.14),0.,1.);}
void main(){vec3 n=normalize(N),view=normalize(eye-P);vec3 base=pow(C,vec3(2.2));float rough=M.y,kind=M.x;
 if(kind>9.5||abs(kind-2.)<.1){float grain=noise(vec2(P.x*1.8,P.z*55.));float rings=sin(P.z*320.+grain*9.+sin(P.x*2.4)*2.);base*=.92+grain*.11+rings*.035;n=normalize(n+vec3(0.,0.,rings*.012));}
 if(abs(kind-1.)<.1){float plaster=noise(P.xy*190.+P.zy*71.);base*=.97+plaster*.055;}
 if(abs(kind-3.)<.1){float weave=sin(P.x*800.)*sin((P.y+P.z)*800.);base*=.97+weave*.035+noise(P.xz*80.)*.025;rough=.97;}
 vec3 L=normalize(vec3(.15,1.,-.85));float ndl=max(dot(n,L),0.),s=shadow(n,L);vec3 lightColor=mix(vec3(1.,.96,.86),vec3(1.,.71,.44),evening);
 float corner=mix(.75,1.,smoothstep(0.,.16,P.y))*mix(.84,1.,smoothstep(0.,.16,P.x+1.6));vec3 ambient=mix(vec3(.53,.57,.6),vec3(.29,.31,.37),evening)*( .86+.14*n.y)*corner;
 vec3 diffuse=lightColor*ndl*s*mix(.85,.34,evening);vec3 lamp=vec3(.28,.21,.12)*max(dot(n,normalize(vec3(.22,1.52,-1.5)-P)),0.)/(1.+dot(P-vec3(.22,1.52,-1.5),P-vec3(.22,1.52,-1.5))*2.);
 float spec=pow(max(dot(n,normalize(L+view)),0.),mix(90.,7.,rough))*(1.-rough)*s;vec3 c=base*(ambient+diffuse+lamp)+lightColor*spec*.22;
 if(abs(kind-5.)<.1){c+=vec3(.11,.16,.18)*pow(1.-max(dot(n,view),0.),3.);}
 if(abs(kind-6.)<.1){c=base*.9+vec3(.06,.075,.07);}
 if(abs(kind-7.)<.1){c+=base*max(dot(-n,L),0.)*.09;}
 gl_FragColor=vec4(pow(film(c*1.18),vec3(1./2.2)),1.);
}`;
const shadowVertex=`attribute vec3 position;uniform mat4 vp;uniform mat4 model;void main(){gl_Position=vp*model*vec4(position,1.);}`;
const shadowFragment=`precision highp float;void main(){vec4 d=fract(min(gl_FragCoord.z,.99999)*vec4(16777216.,65536.,256.,1.));d-=d.xxyz*vec4(0.,1./256.,1./256.,1./256.);gl_FragColor=d;}`;
export class RoomRenderer{
 constructor(canvas,meshes){this.gl=canvas.getContext('webgl',{antialias:true,alpha:false});if(!this.gl)throw Error('WebGLを開始できません');this.canvas=canvas;const gl=this.gl;this.program=this.programFor(vertex,fragment);this.shadowProgram=this.programFor(shadowVertex,shadowFragment);this.lightVP=multiply(ortho(-3,3,-3,3,.1,10),lookAt([.5,2.5,-1.68],[.1,.3,.2]));this.parts=meshes;this.objects=[];const staticParts=meshes.filter(m=>!m.interaction),shadowParts=staticParts.filter(m=>!/window dark|sheer curtain|screen|diffuser/i.test(m.name));this.static=this.upload(staticParts);this.shadowStatic=this.upload(shadowParts);this.items={};for(const id of ['book','note','phone','archive'])this.items[id]=this.upload(meshes.filter(m=>m.interaction===id));this.hand=this.upload(makeHand());this.setupShadow();this.shadowDirty=true;this.lastHeld=null;gl.enable(gl.DEPTH_TEST);gl.enable(gl.CULL_FACE);}
 programFor(vs,fs){const gl=this.gl,p=gl.createProgram();for(const[type,src]of[[gl.VERTEX_SHADER,vs],[gl.FRAGMENT_SHADER,fs]]){const s=gl.createShader(type);gl.shaderSource(s,src);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(s));gl.attachShader(p,s);}gl.linkProgram(p);if(!gl.getProgramParameter(p,gl.LINK_STATUS))throw Error(gl.getProgramInfoLog(p));return p;}
 upload(parts){const gl=this.gl,data=pack(parts),buffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.bufferData(gl.ARRAY_BUFFER,data,gl.STATIC_DRAW);return{buffer,count:data.length/12};}
 setupShadow(){const gl=this.gl;this.shadowTexture=gl.createTexture();gl.bindTexture(gl.TEXTURE_2D,this.shadowTexture);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,1024,1024,0,gl.RGBA,gl.UNSIGNED_BYTE,null);for(const p of [gl.TEXTURE_MIN_FILTER,gl.TEXTURE_MAG_FILTER])gl.texParameteri(gl.TEXTURE_2D,p,gl.NEAREST);for(const p of [gl.TEXTURE_WRAP_S,gl.TEXTURE_WRAP_T])gl.texParameteri(gl.TEXTURE_2D,p,gl.CLAMP_TO_EDGE);this.shadowFB=gl.createFramebuffer();gl.bindFramebuffer(gl.FRAMEBUFFER,this.shadowFB);gl.framebufferTexture2D(gl.FRAMEBUFFER,gl.COLOR_ATTACHMENT0,gl.TEXTURE_2D,this.shadowTexture,0);const depth=gl.createRenderbuffer();gl.bindRenderbuffer(gl.RENDERBUFFER,depth);gl.renderbufferStorage(gl.RENDERBUFFER,gl.DEPTH_COMPONENT16,1024,1024);gl.framebufferRenderbuffer(gl.FRAMEBUFFER,gl.DEPTH_ATTACHMENT,gl.RENDERBUFFER,depth);this.hasShadow=gl.checkFramebufferStatus(gl.FRAMEBUFFER)===gl.FRAMEBUFFER_COMPLETE;gl.bindFramebuffer(gl.FRAMEBUFFER,null);}
 drawMesh(mesh,model,program){const gl=this.gl;gl.bindBuffer(gl.ARRAY_BUFFER,mesh.buffer);for(const[name,offset]of[['position',0],['normal',3],['color',6],['material',9]]){const loc=gl.getAttribLocation(program,name);if(loc>=0){gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,3,gl.FLOAT,false,48,offset*4);}}gl.uniformMatrix4fv(gl.getUniformLocation(program,'model'),false,model);gl.drawArrays(gl.TRIANGLES,0,mesh.count);}
 render({vp,eye,evening,held,itemModel,handModel}){const gl=this.gl,I=identity();if(this.lastHeld!==held){this.shadowDirty=true;this.lastHeld=held;}if(this.hasShadow&&this.shadowDirty){gl.bindFramebuffer(gl.FRAMEBUFFER,this.shadowFB);gl.viewport(0,0,1024,1024);gl.clearColor(1,1,1,1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.useProgram(this.shadowProgram);gl.uniformMatrix4fv(gl.getUniformLocation(this.shadowProgram,'vp'),false,this.lightVP);this.drawMesh(this.shadowStatic,I,this.shadowProgram);for(const id of Object.keys(this.items))if(id!==held)this.drawMesh(this.items[id],I,this.shadowProgram);gl.bindFramebuffer(gl.FRAMEBUFFER,null);this.shadowDirty=false;}
 const ratio=Math.min(devicePixelRatio||1,1.75),w=Math.round(innerWidth*ratio),h=Math.round(innerHeight*ratio);if(this.canvas.width!==w||this.canvas.height!==h){this.canvas.width=w;this.canvas.height=h;}gl.viewport(0,0,w,h);gl.clearColor(.7,.69,.64,1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.useProgram(this.program);gl.uniformMatrix4fv(gl.getUniformLocation(this.program,'vp'),false,vp);gl.uniformMatrix4fv(gl.getUniformLocation(this.program,'lightVP'),false,this.lightVP);gl.uniform3fv(gl.getUniformLocation(this.program,'eye'),eye);gl.uniform1f(gl.getUniformLocation(this.program,'evening'),evening);gl.uniform1f(gl.getUniformLocation(this.program,'hasShadow'),this.hasShadow?1:0);gl.activeTexture(gl.TEXTURE0);gl.bindTexture(gl.TEXTURE_2D,this.shadowTexture);gl.uniform1i(gl.getUniformLocation(this.program,'shadowMap'),0);this.drawMesh(this.static,I,this.program);for(const[id,obj]of Object.entries(this.items))this.drawMesh(obj,id===held?itemModel:I,this.program);if(handModel)this.drawMesh(this.hand,handModel,this.program);}
}
// A small articulated hand and sleeve, in camera-relative coordinates.
function makeHand(){const parts=[];function ell(name,c,r,col){const positions=[],point=(a,b)=>[c[0]+Math.sin(a)*Math.cos(b)*r[0],c[1]+Math.cos(a)*r[1],c[2]+Math.sin(a)*Math.sin(b)*r[2]];for(let i=0;i<10;i++)for(let j=0;j<16;j++){const a=.002+i/10*(Math.PI-.004),b=j/16*Math.PI*2,A=point(a,b),B=point(a,b+Math.PI/8),C=point(a+(Math.PI-.004)/10,b+Math.PI/8),D=point(a+(Math.PI-.004)/10,b);positions.push(...A,...B,...C,...A,...C,...D);}parts.push({name,positions,color:col,smooth:true,kind:col==='#b58d73'?'skin':null});}
 ell('Cotton sleeve',[.015,-.155,.1],[.065,.19,.065],'#737a72');ell('Wrist',[0,-.025,.0],[.041,.07,.034],'#b58d73');ell('Palm',[0,.045,-.018],[.052,.076,.027],'#b58d73');
 for(let i=0;i<4;i++){const x=-.039+i*.024,y=.112+([-.012,.005,.012,-.002][i]);ell('Finger',[x,y,-.032],[.012,.044,.013],'#b58d73');ell('Fingertip',[x,y+.029,-.05],[.012,.019,.018],'#b58d73');}ell('Thumb',[-.06,.052,-.032],[.023,.037,.02],'#b58d73');return parts;}
